PrologProcedure:
#****Begin: Generated Statements***
#****End: Generated Statements****

################################################################################################# 
##~~Join the bedrock TM1 community on GitHub https://github.com/cubewise-code/bedrock Ver 4.0.0~~##
################################################################################################# 

#Region @DOC
# Description:
# This process creates a view that can be used for exporting, copying or zeroing out numbers.

# Use case: Intended for development/prototyping or production.
# 1/ Create a view to zero out data.
# 2/ Create a view to use as a source for exporting or copying.

# Note:
# Naturally, a valid cube name (pCube) is mandatory otherwise the process will abort.
# The pFilter parameter contains the dimenson and elements to be used for filtering:
# - The format of the pFilter parameter is as follows delimiters of :, & and +: Dim1: Elem1 + Elem2 & Dim2: Elem3 + Elem4.
# - The dimension parameters do not need to be given in the index order of dimensions in the cube.
# - The dimension name is specified as the first member of the delimited string of elements.
# - If consols are skipped the N level children of any consolidated filter elements will be used.
# - Spaces are ignored so use them to make your filter more readable.
# - pTemp: This parameter will control whether to make the view temporary (value 1) or if the
#   view will be permanently retained (value 0).
#EndRegion @DOC

### Global Variables
pJson = IF( pJson @= '', '{}', pJson );
StringGlobalVariable(  'sBedrockReturnValue' );
NumericGlobalVariable( 'nBedrockReturnValue' );

### Constants ###
cThisProcName   = GetProcessName();
cUserName       = TM1User();
cTimeStamp      = TimSt( Now, '\Y\m\d\h\i\s' );
cRandomInt      = NumberToString( INT( RAND( ) * 1000000000 ));
cTemp           = cThisProcName |'_'| cTimeStamp |'_'| cRandomInt;
sErrorMessage   = '{"Process": "'|cThisProcName|'", "User": "'|cUsername|'", "Messages":[]}';
sInfoMessage    = '{"Process": "'|cThisProcName|'", "User": "'|cUsername|'", "Messages":[]}';


#################################################################################################
#Region - Process Parameters

pJson = IF( JsonType( pJson ) @<> 'object', '{}', pJson );
sMessages = '{"Process": "'|GetProcessName()|'", "User": "'|TM1User()|'", "Info": ["Process: '''|GetProcessName()|''' run by User: '''|TM1User()|'''."], "Error": []}';
pDefaultParameters = '{
  "pItemDelimiter":       ";",
  "pKeyValueDelimiter":   "=",
  "pString":              null,
  "pCASIKeys":            0,
  "pLogOutput":           0,
  "pStrictErrorHandling": 0
}';

pPassedParameters = '{
  "pItemDelimiter":       '|StringToJson  ( pItemDelimiter       )|',
  "pKeyValueDelimiter":   '|StringToJson  ( pKeyValueDelimiter   )|',
  "pString":              '|StringToJson  ( pString              )|',
  "pCASIKeys":            '|NumberToString( pCASIKeys            )|',
  "pLogOutput":           '|NumberToString( pLogOutput           )|',
  "pStrictErrorHandling": '|NumberToString( pStrictErrorHandling )|'
}';

pJson = JsonMergePatch( pPassedParameters, pJson );
# String Parameters
pItemDelimiter       =                 JsonToString( JsonGet( pJson, 'pItemDelimiter'     ) );
pKeyValueDelimiter   =                 JsonToString( JsonGet( pJson, 'pKeyValueDelimiter' ) );
pString              =                 JsonToString( JsonGet( pJson, 'pString'            ) );
# Numeric Parameters
pCASIKeys            = StringToNumber( JsonToString( JsonGet( pJson, 'pCASIKeys'          ) ) );
pLogOutput           = StringToNumber( JsonToString( JsonGet( pJson, 'pLogOutput'         ) ) );
pStrictErrorHandling = StringToNumber( JsonToString( JsonGet( pJson, 'pStrictErrorHandling' ) ) );

### Get the parameters that differ from the default
pDiffer = JsonDiff( pDefaultParameters, pJson );
nSize = JsonSize( pDiffer );
WHILE( nSize > 0 );
  nSize = nSize - 1;
  pDiffer = JsonReplace( pDiffer, '/'|NumberToString( nSize )|'/op', '"add"' );
END;
pJson = JsonPatch( '{}', pDiffer );

### LogOutput parameters
sMessages = JsonAdd( sMessages, '/Info/-', pJson );
IF( pLogOutput = 1 );
  LogOutput('INFO', JsonToString( sMessages, '/Info/0', 0, ' ' ) );
ENDIF;

#EndRegion - Process Parameters
#################################################################################################

nDelimiterLength = LONG( pKeyValueDelimiter );
# Convert pFilter to JSON array of key-value pairs
ExecuteProcess( '}bedrock.utils.string.to_list', 'pString', pString, 'pDelimiter', pItemDelimiter );
sArray = sBedrockReturnValue;
sReturnValue = '{}';

WHILE( JsonSize( sArray ) > 0 );
  sElement = JsonToString( JsonGet( sArray, '/0' ) );
  sArray = JsonRemove( sArray, '/0' );
  
  nDelimiterIndex = SCAN( pKeyValueDelimiter, sElement );
  IF( nDelimiterIndex <> 0 );
    sKey = SUBST( sElement, 1, nDelimiterIndex - 1 );
    sVal = StringToJson( SUBST( sElement, nDelimiterIndex + nDelimiterLength, LONG( sElement ) ) );
  ELSE;
    sKey = sElement;
    sVal = 'null';
  ENDIF;
  
  #CASI Key
  IF( pCASIKeys = 1 );
    WHILE( SCAN( ' ', sKey ) <> 0 ); sKey = DELET( sKey, SCAN( ' ', sKey), 1 ); END; sKey = LOWER( sKey );
  ENDIF;
  
  sReturnValue = JsonAdd( sReturnValue, sKey, sVal );
END;
sBedrockReturnValue = sReturnValue;
